USE `tcg`;
SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS `test_cases`;
CREATE TABLE `test_cases` (
  `id` int NOT NULL AUTO_INCREMENT,
  `external_ref` varchar(45) DEFAULT NULL,
  `project_id` int DEFAULT NULL,
  `userstory_id` int DEFAULT NULL,
  `requirment_id` int DEFAULT NULL,
  `technique` varchar(100) DEFAULT NULL,
  `summary` longtext,
  `test_steps` blob,
  `expected_result` longtext,
  `test_data` blob,
  `created` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `accepted` tinyint DEFAULT '0',
  `priority` varchar(45) DEFAULT NULL,
  `tags` blob,
  `tobeautomate` tinyint DEFAULT '0',
  `regression` tinyint DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=38219 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO `test_cases` (`id`,`external_ref`,`project_id`,`userstory_id`,`requirment_id`,`technique`,`summary`,`test_steps`,`expected_result`,`test_data`,`created`,`updated`,`accepted`,`priority`,`tags`,`tobeautomate`,`regression`) VALUES
(26063,NULL,103,1105,3503,'Use Case Testing','STC_19 and 20 -Verify Warehouse transfer Shipment and Warehouse shipment receive','["Launch the IMS application and navigate to the Login page","Enter a valid username in the Username field","Enter a valid password in the Password field","Click the Login button","Click the Edit Company icon","Select PPMTL","Click Intransit from the left navigation menu","Click the Warehouse Transfer button","Fill From Location field with From Location value","Select PPMTL from the autocomplete suggestions","Fill autocomplete-toLocation field with To Location value","Select ECLIPS from the autocomplete suggestions","Click the Find button to search for products","Click the Search Button","Select the checkbox for the Product ID where Actual Yard Stock is greater than 0 and Stock on S/O is equal to 0","Click the Add Products button","Click the Create Bulk Intransit button","Verify that the Close Intransit button is displayed","Capture the Transit ID displayed near the Intransit Details header","Click the Close (X) button","Click Purchase Order from the left navigation menu","Click the Expand button in the left navigation panel","Click Intransit from the left navigation menu","Click Intransit Shipment","Expand the Status dropdown","Select the Open Option","Enter the captured Transit ID in the search field","Click the Search button","Click the Edit button for the matching search result","Enter the shipping carrier and select respective option","Enter the Carrier BOL Number","Click the Pick All button","Click OK if the confirmation dialog appears","Click the Generate Picklist button","Click the Print button","Click on Print Picklist button","Click the Generate BOL button","Wait for Page to be loaded","Click the Close (X) button","Click Intransit button","Click Receive Transit button","Enter the captured Transit ID in the search field","Click the Search button for Transit ID","Select row checkbox for the result row","Click the Edit button","Capture the Product ID from the Product ID column in the first row of the grid","Click the Receive All button","Click OK on confirmation popup","Click Receive Inventory button","Click OK on the confirmation dialog","Click the Close (X) button","Click Inventory from the left navigation menu","Click Inventory History button","Enter the captured Product ID in the Product field","Click the Search button for product","Verify Search Inventory grid has a single row or more for the filtered product, description references ERW pipe as commercial damaged, and all three stock groups show no quantity in pieces or feet"]','BOL should be generated and print BOL button should be enabled on the top under print button','["\\"Login URL: https://ims.sws.pipe-piling.com/auth/ims/login/?returnTo=%2Fdashboard%2Fims-order%2Flist%2F","Username: Nitesh","Password: ofbiz","Transit ID: 217241","Shipping Carrier (dropdown): ADA100US - ADA LOGISTICS CORP","Carrier BOL#: BT16177123","",""]','2025-07-02 17:36:42','2026-08-13 06:22:20',1,'P1','["functional", "ui"]',1,0),
(26064,NULL,103,1105,5507,'Use Case Testing','DSTC_87 - Verify assigned user(user with access to PO in PPUSA) is able to create purchase order','["Open the login page","Enter Username","Enter Password","Click Login button","Click Edit company icon","Select PPUSA SENECA","Click Purchase Order from left menu","Click the Create New PO button","Click Find in Supplier label","Enter Supplier ID","Click Search button","Click Add","Enter Ship to Location input field","Click SUPPLIER-USA","Enter Pick Up Location input field","Click ECLIPS","Click Find in Enter Product ID label","Click Open in Product Type label","Select BEAMS","Click Search (in Supplier modal)","Click checkbox in product id whose Actual Yard Stock greater than 0 and stock on S/O equals zero","Click Add Products","Click Qty Ordered","Enter Qty Ordered","Click outside grid","Click Unit Price","Enter Unit Price","Click outside grid","Click Create button","Click OK on confirmation popup","Verify PO number displayed in Purchase Order Edit screen","Click on Print PO button and Verify PO pdf should be opened in new tab and all the PO details should be display"]','Verify below things 1. Create purchase order screen should be open with all the fields blank like supplier-USA yard etc. 2. Added details like supplier, yard, items should be show on the screen. 3. PO should be created with id entered by user with created status and same PO should be show on PO list screen. 4. PO pdf should be opened with all the PO details."','["Login URL: https://ims.sws.pipe-piling.com/auth/ims/login/?returnTo=%2Fdashboard%2Fims-order%2Flist%2F","Username: Nitesh","Password: ofbiz",""]','2025-07-02 17:36:42','2026-08-15 18:05:22',1,'P1','["functional", "ui"]',1,0),
(37713,NULL,103,1101,5493,'Optimized','RTC_03- Validate the create order with valid inputs ','["Navigate to the Url","Enter a valid username","Enter a valid password","Click on login button","Click on button create new order","Enter Find bill address","Click on find","Click on add.","Fill Customer PO# field","Fill Project Name=Test Field","Click on the find button beside Enter product ID input field.","Observe Product type are showing Prefilled","Enter OD and Wallt RangeTo and then click search button"," Select any two item from the list by checkbox and click Add products button","Update the Qty Order and price for both the items one by one","Check Total ($) value on line is updated correctly as per the Qty and Price","Click Save button on top and observer below items on Order screen.","Check Unique Order id is created","Click on print button"]','User is successfully authenticated and redirected to the Order','["Username:Arun1","Password:ofbiz","Url: https://ims.sws.pipe-piling.com/dashboard/ims-order/list/","Find bill address=Ace Excavating Ltd.","Customer PO#=Test123","Project Name=Test","ODRange To- 24.000","WalltRange To-0.500",""]','2026-04-10 07:13:26','2026-07-25 16:36:51',1,'P1','["functional", "regression", "smoke"]',1,1),
(37714,NULL,103,1101,5493,'Optimized','Exclude-Verify Purchase Order listing screen and search options','["Navigate to the Url","Enter a valid username","Enter a valid password","Click on login button"]','User is authenticated even with uppercase username provided, and redirected to dashboard','["Username:Arun1","Password:ofbiz","Url: https://ims.sws.pipe-piling.com/dashboard/ims-order/list/"]','2026-04-10 07:13:26','2026-04-27 09:30:34',1,'P1','["functional", "regression", "authentication"]',1,0),
(37715,NULL,103,1101,5493,'Optimized','RTC_04-Verify Purchase Order listing screen and search options','["Navigate to the Url","Enter a valid username","Enter a valid password","Click on login button","Navigate to Purchase Order from the left menu bar","Search for existing PO# by entering the PO# and click search","Click reset button","Enter the supplier name and click search"]','User remains authenticated and redirected to the dashboard without re-inputting credentials','["Username:Arun1","Password:ofbiz","Url: https://ims.sws.pipe-piling.com/dashboard/ims-order/list/","PO#-2673-PO","supplier name -Shoreline Steel South, LLC"]','2026-04-10 07:13:26','2026-07-25 16:37:00',1,'P2','["functional", "persistence", "state-management"]',1,0),
(37716,NULL,103,1101,5494,'Optimized','Validate that user is able to login with valid credentials and session validation','["Navigate to the application login page","Enter a valid username field","Enter password in the password field","Click the Login button","Check Order module tab is displaying on the left menu"," Check session persists if user navigates across multiple modules"]','System displays error message indicating \'Incorrect password with valid email - error message displayed\' and prevents dashboard redirection','["Username:Arun1","Password:ofbiz","Url: https://ims.sws.pipe-piling.com/dashboard/ims-order/list/"]','2026-04-10 07:13:26','2026-04-27 07:35:35',1,'P1','["functional", "negative", "security"]',1,0),
(37717,NULL,103,1101,5494,'Optimized','TC-02-Validate the Order listing page and search for existing orders','["Navigate to the url","Enter a valid Username ","Enter a valid password","Click the Login button","Click on the order module from the left menu","Click Order status dropdown has  Approved and Created options default selected","Click Order status dropdown again","Click on OrderID","Enter the valid Order id in Order# input field and hit search","Click on the reset button to clear the last search option ","Enter the Customer name with order already posted in Customer name and click search button","Click the Reset button after search and then observe if entered Sales Order# or customer name is cleared from the search screen","Click the Reset button after search and then observe if entered Sales Order# or customer name is cleared from the search screen and now select deposit checkbox and click search button"]','System displays appropriate error message for \'Incorrect email with valid password - error message displayed\' or \'User does not exist - appropriate error message displayed\' and both incorrect input scenarios','["Username:Arun1","Password:ofbiz","Url: https://ims.sws.pipe-piling.com/dashboard/ims-order/list/","Order#:BC25297","customer name:ABD Boats"]','2026-04-10 07:13:26','2026-05-05 14:32:00',1,'P1','["functional", "negative", "validation"]',1,0),
(37718,NULL,103,1101,5494,'Optimized','TC_05- Verify Purchase Order creation','["Navigate to the Url","Enter a valid username","Enter a valid password","Click on login button","Navigate to Purchase Order from the left menu bar","Click plus button for Create new PO","Enter supplier detils click on find",""]','','["Username:Arun1","Password:ofbiz","Url: https://ims.sws.pipe-piling.com/dashboard/ims-order/list/"]','2026-04-10 07:13:26','2026-05-04 08:25:11',1,'P1','["functional", "negative", "security"]',1,0),
(37719,NULL,103,1101,5495,'Optimized','Validate login failure for empty username, empty password, and special characters only in username field','["Navigate to the Login Page", "Enter empty value in the Username field", "Enter empty value in the Password field", "Alternatively, enter only special characters in the Username field", "Click the Login Button", "Validate the error messages and system response"]','System displays a validation error message for empty username, empty password, and username with only special characters; does not redirect to dashboard.','[" (Empty string)", " (Empty string)", " !!!@@# (Special characters only)"]','2026-04-10 07:13:26','2026-04-10 07:13:26',0,'P1','["functional", "security", "validation"]',1,0),
(37720,NULL,103,1101,5495,'Optimized','Validate login failure for invalid email format and password shorter than minimum length','["Navigate to the Login Page", "Enter invalid email format (missing @ or no TLD) in the Username field", "Enter password with less than 8 characters in the Password field", "Click the Login Button", "Validate the error messages and system response"]','System displays a validation error message specifically addressing the invalid email format and password length requirements; login is not successful.','["user@.com (Missing @)", "12345 (Short password)"]','2026-04-10 07:13:26','2026-04-10 07:13:26',0,'P1','["functional", "regression", "password-policy"]',1,0),
(37721,NULL,103,1101,5495,'Optimized','Validate login failure for username with spaces, email username too long, and password with only whitespace','["Navigate to the Login Page", "Enter username containing only space characters", "Enter email username portion that exceeds maximum length limit", "Enter password containing only whitespace characters", "Click the Login Button", "Validate the error messages and system response"]','System displays appropriate validation error messages for whitespace-only password, long email username, and space-only username; access to dashboard is denied.','["   (Spaces only)", "a@veryveryverylongdomainnamethatexceedstheallowedlimitforthemailboxusernameportion (Long email part)", "   (Whitespace only)"]','2026-04-10 07:13:26','2026-04-10 07:13:26',0,'P1','["functional", "input-boundaries", "validation"]',1,0),
(37722,NULL,103,1101,5496,'Optimized','Verify Password Security, Length, and Character Handling Including Case Sensitivity and Whitespace','["Navigate to the Login page.", "Select a username/email that is verified valid in the system.", "Enter a password exceeding the maximum length limit (e.g., 150 characters) in the password field.", "Add special unicode characters (e.g., !@#$%^&*) to a short password.", "Ensure the password contains both uppercase and lowercase letters.", "Introduce tabs or spaces within the password field before clicking submit.", "Observe the error message or redirect behavior.", "Verify if login succeeds or fails based on policy configuration."]','System handles long password gracefully (error message if too long or success if limit is exceeded but policy allows, or truncation error). Special characters must pass validation if supported. Case sensitivity must match stored credentials. Tabs/spaces must trigger validation errors or be stripped depending on policy, showing appropriate message.','["Password: Aaaaaaaaaaaaaaaa... (100+ chars)", "Password: P@ssw0rd!#$%^&()*()", "Password: Pa$$word (Mixed Case)", "Password: Pass_word_with_space (Tab/Space injection)"]','2026-04-10 07:13:27','2026-04-10 07:13:27',0,'P1','["Authentication", "Security", "Input_Validation", "Functional"]',1,0),
(37723,NULL,103,1101,5496,'Optimized','Validate Username and Email Format Limits including IDN Support and Long Lengths','["Navigate to the Login page.", "Enter a username with 30+ characters.", "Enter an email address exceeding the character length limit.", "Enter an email address using International Domain Name (IDN) format.", "Enter an email with valid format but no username (edge case).", "Submit the login details.", "Verify the system response for length violations and format support."]','Username exceeding 30 characters should be accepted if backend policy allows or rejected with clear message. Long email addresses should be handled gracefully with appropriate error. IDN emails should be supported with clear acceptance or rejection message if not supported.','["Username: user_name_with_35_characters_long", "Email: very.long.email.address.with.many@characters.com", "Email: example@ex\\u00e4mple.com", "Email: user@unsupported.tld (IDN unsupported)"]','2026-04-10 07:13:27','2026-04-10 07:13:27',0,'P2','["Authentication", "Validation", "Format_Check", "Functional"]',1,0),
(37724,NULL,103,1101,5496,'Optimized','Check System State Handling During Account Reset and Graceful Error Display','["Trigger a password reset or account maintenance status for the current user account via backend.", "Navigate to the Login page.", "Enter correct credentials for the account currently in reset or maintenance mode.", "Submit the login form.", "Observe the system response.", "Verify that the system does not allow login and displays a specific \'Account Action in Progress\' message.", "Ensure no session timeout errors occur during this state."]','Login request is blocked gracefully. Error message indicates the account is being reset or locked. System should not crash. Status is returned correctly (e.g., 403 or specific custom error status).','["Account State: Resetting", "Message: \'Account is being reset, please try again later\'", "Account State: Locked"]','2026-04-10 07:13:27','2026-05-04 09:06:46',0,'P1','["Authentication", "State_Manager", "Error_Handling", "Critical"]',1,0),
(37725,NULL,103,1101,5497,'Optimized','Verify successful login and order creation flow','["Navigate to the URL","Enter a valid username","Enter a valid password","Verify password field is displayed","Verify Login button is displayed","Click on login button","Verify Search Orders text is displayed","Click on button create new order","Enter bill address in Find bill address search box","Click on find icon","Click on add button","Fill Customer PO# field","Fill Project Name field","Click on the find button beside Enter product ID input field","Validate Product type combobox is Prefilled","Enter OD Range To","Enter Wallt Range To","Click search button","Select first item from the list by checkbox","Select second item from the list by checkbox","Click Add products button","Click Save button","Check Unique Order id is created","Click on print button","Wait for 5 seconds","Take screenshot of the page"]','Order should created with orderId','["Username:Arun1","Password:ofbiz","Url: https://ims.sws.pipe-piling.com/dashboard/ims-order/list/","bill address=Ace Galvanizing, Inc.","Customer PO#=Test123","Project Name=Test","ODRange To- 24.000","WalltRange To-0.500"]','2026-04-10 07:13:27','2026-04-22 09:52:23',1,'P1','["functional", "integration", "security"]',1,0),
(37726,NULL,103,1101,5497,'Optimized','Demo Scenario for first time use','["Navigate to the URL","Enter a valid username","Enter a valid password","Verify password field is displayed","Verify Login button is displayed","Click on login button","Verify Search Orders text is displayed","Click on button create new order","Enter bill address in Find bill address search box","Click on find icon","Click on add button","Fill Customer PO# field","Fill Project Name field","Click on the find button beside Enter product ID input field","Validate Product type combobox is Prefilled","Enter OD Range To","Enter Wallt Range To","Click search button","Select first item from the list by checkbox","Select second item from the list by checkbox","Click Add products button","Click Save button","Check Unique Order id is created","Click on print button","Wait for 5 seconds","Take screenshot of the page"]','Order should be created successfully','["Username:Arun1","Password:ofbiz","Url: https://ims.sws.pipe-piling.com/dashboard/ims-order/list/","bill address=Ace Galvanizing, Inc.","Customer PO#=Test123","Project Name=Test","ODRange To- 24.000","WalltRange To-0.500"]','2026-04-10 07:13:27','2026-04-22 11:02:12',1,'P1','["integration", "security", "sso"]',1,0),
(37727,NULL,103,1101,5497,'Optimized','Verify system resilience under load and invalid credential handling','["Initiate login script with 50 concurrent threads.", "Attempt login with invalid credentials intermittently.", "Perform login from different network devices.", "Verify error message display for invalid credentials.", "Verify no session conflicts under load."]','System handles gracefully under load. Invalid credentials show error message. Session management validated across devices. No crashes.','["invalid_password", "valid_username", "load_concurrency_level", "device_network_type"]','2026-04-10 07:13:27','2026-04-10 07:13:27',0,'P1','["performance", "functional", "integration"]',1,0),
(37728,NULL,103,1101,5498,'Optimized','Verify input sanitization for SQL Injection and XSS across email/password fields and credential stuffing prevention','["Navigate to the Login page.", "In the email field, enter a payload: \\\\\' OR \\\\\'1\\\\\'=\\\\\'1\\\\\' #", "In the password field, enter a payload: <script>alert(document.cookie)</script>", "Attempt to submit the login form.", "Wait for system response."]','Login request is rejected. SQL injection payload triggers validation error message. XSS payload triggers validation error message. Credential stuffing attempts with invalid data are blocked.','["\\"\\\\\' OR \\\\\'1\\\\\'=\\\\\'1\\\\\' #\\"", "\\"<script>alert(document.cookie)</script>\\"", "\\"invalid_user@example.com\\"", "\\"wrong_password_1\\"", "\\"wrong_password_2\\"", "\\"wrong_password_3\\"", "\\"wrong_password_4\\""]','2026-04-10 07:13:27','2026-04-10 07:13:27',0,'P1','["security", "input_validation", "injection_prevention"]',1,0),
(37729,NULL,103,1101,5498,'Optimized','Verify session security management including hijacking prevention and idle session expiration enforcement','["Login successfully to get a valid session token.", "Copy the session token to a different browser or client.", "Attempt to access the dashboard using the stolen session token from the new client.", "Attempt to login again after 30 minutes of inactivity on the user account.", "Observe dashboard redirection behavior."]','Invalid session rejected due to hijacking attempt. User session automatically expired after idle time. User is redirected to login page or shown an expired session message.','["\\"Stolen_Session_Token_ABC123\\"", "\\"Expired_Session_Token_ZYX987\\"", "\\"valid_session_Token_123\\""]','2026-04-10 07:13:27','2026-04-10 07:13:27',0,'P1','["security", "session_management", "token_validation"]',1,0),
(37730,NULL,103,1101,5498,'Optimized','Verify infrastructure protections including MITM certificate validation, secure logging, and rate limiting on failed attempts','["Configure HTTP Proxy man-in-the-middle simulation.", "Attempt to establish connection via invalid SSL certificate domain.", "Attempt 5+ rapid login attempts with wrong password.", "Log out and inspect application server logs for failed login entries.", "Check logs for presence of plaintext password or session tokens."]','Connection rejected with SSL/TLS certificate error. Login attempts blocked after limit is reached. Sensitive credentials not logged in plaintext. Logs only contain user ID or hash.','["\\"https://malicious-proxy.intra.com\\"", "\\"user@example.com\\"", "\\"wrong_password\\""]','2026-04-10 07:13:27','2026-05-04 09:07:22',1,'P1','["security", "network_security", "audit_logging"]',0,0),
(37731,NULL,103,1101,5499,'Optimized','Verify keyboard navigation flow, visible focus indicators, and error message contrast on login page','["Navigate to the Login page using Tab key until all interactive elements are reachable", "Ensure focus indicator (outline) is clearly visible on Email and Password fields", "Enter invalid credentials and trigger error message", "Verify error text color has sufficient contrast ratio against background per WCAG 2.1"]','Tab order is logical, focus ring is distinct, and error text is readable','["Email field", "Password field", "Error Message"]','2026-04-10 07:13:27','2026-04-10 07:13:27',0,'P1','["accessibility", "ui", "visual"]',0,0),
(37732,NULL,103,1101,5499,'Optimized','Validate screen reader compatibility, ARIA labels, and error announcements via assistive technology','["Open login page using screen reader software (JAWS/NVDA)", "Ensure Email and Password fields announce with correct type and \'username\'/\'password\'"]','Screen reader announces fields with correct labels, and error messages are spoken upon focus change','["test_user", "invalid_pass"]','2026-04-10 07:13:28','2026-04-10 07:13:28',0,'P1','["accessibility", "screen-reader"]',0,0),
(37733,NULL,103,1101,5499,'Optimized','Confirm password input masking and \'Login\' button accessible name functionality','["Focus on Password input field", "Type characters and verify they are obscured", "Tab to Login button and verify accessible name is \'Login\' in accessibility tree", "Submit credentials for successful flow"]','Password characters hidden, Button name identified by screen reader','["Password123!"]','2026-04-10 07:13:28','2026-04-10 07:13:28',0,'P1','["accessibility", "security"]',1,0),
(37734,NULL,103,1101,5500,'Optimized','Verify successful login process with correct labels and loading indicators','["Navigate to the Login Page", "Verify field labels \'Email\' and \'Password\' are displayed correctly next to inputs", "Enter valid email address and password credentials", "Click on the \'Submit\' button", "Verify loading indicator appears during credential validation", "Wait for successful authentication", "Verify browser redirects to the dashboard successfully"]','User is redirected to the dashboard after successful login and all visual indicators (labels, loading) appear as expected','["Email: user@example.com", "Password: SecurePass123!"]','2026-04-10 07:13:28','2026-04-10 07:13:28',0,'P1','["functional", "UI"]',1,0),
(37735,NULL,103,1101,5500,'Optimized','Verify error handling, password strength, and form reset on invalid submission','["Navigate to the Login Page", "Verify field labels match input fields", "Enter invalid email or password credentials", "Observe real-time password strength indicator feedback", "Click on the \'Submit\' button", "Verify error message is clear, actionable, and guidance to fix provided", "Ensure form fields reset and clear after submission failure"]','Clear error message displayed, password strength indicator updates correctly, and input fields are cleared upon invalid submission','["Email: wrong-email.com", "Password: weak"]','2026-04-10 07:13:28','2026-05-04 09:01:24',1,'P1','["functional", "error_handling"]',1,1),
(37736,NULL,103,1101,5500,'Optimized','Verify toggle fucntionality','["Navigate to the Url","Enter a valid username","Enter a valid password","Click on login button","Click on toggle button on top left side","Click plus button on Purchase Order list screen","Add the supplier in the Purchase order by clicking the find icon on Supplier details","Enter Shipping details destination location- this should be the same as item location in the last sales order",""]','toggle button should be clicked successfully','["Username:Arun1","Password:ofbiz","Url: https://ims.sws.pipe-piling.com/dashboard/ims-order/list/"]','2026-04-10 07:13:28','2026-05-04 10:34:35',1,'P2','["functional", "ux"]',1,0),
(37737,NULL,103,1104,5501,'Optimized','STC_11 Verify user is able to generate the picklist and BOL and Inventory is reduced for the shipped item in the shipment from the Inventory history screen','["  Launch and navigate to the IMS login page using url","  Enter the valid username and password in their respective field","  Click on the \'Login\' button","  Click on Order button from left nav","  Assert: Verify grid columns - S/O, S/O NO $, Order #, Customer Name, Project Name, Customer PO #, User Comments, Vendor PO #, Deposit, Salesman, Order Date, Last Shipped Date, Currency, Status","  Click on Create New Order button","  Enter Supplier Party Id(Find Bill Address) ","  Click the Find button (magnifying glass icon) inside the \\"Find Bill Address\\" field.","  Click on Search Button.","  Assert: The visible row count is ≥ 1","  Click on title Add button","  Click on title Find button for searchProduct(Enter Product Id) field","  Wait for 2 second and click on Search button","  Capture the first product on where Stock on S/O (PCS) = 0 and Actual Yard Stock (PCS) > 0","  Click on Captured product checkbox","  Click on title Add Products button","  Wait for 2 sec and click on save button","  Capture Order # caption near Edit Order and store for future use.","  Click on menu-button (Order Actions)","  Click on menu item (Approve Order)","  Click on svg cross icon ( iconify--simple-line-icons )","  Click on Shipping button from left nav","  Assert: Verify grid columns - Order #, BOL #, Load #, Reference #, Invoice #, Carrier BOL #, Shipment Status, Customer Name, Project Name, Customer PO #, Vendor PO #, Status, ETA, Order Date","  FIll captured Order # in Order #","  Click on submit button","  Click on first edit button of the row","  Wait for 5 seconds and fill autocomplete-shippingCarrier(Shipping Carrier)","  FIll data field qtyToShip (gridcell) with qtyValue","  Wait for 2 seconds and click on Generate Picklist button","  Click on print-button (Print)","  Click on menuitem Print Picklist","  Wait for load state","  Assert: Parse the pdf and verify - ITEM #, Description, Location, Qty To Pick (Pcs), WEIGHT (lbs), Qty Picked, Heat Number, Total, SOLD TO:, Name Of Carrier:, SHIP TO:","  Move page to front where url contains url-part","  Wait for load state","  Click on Generate BOL button","  Assert: Button \\"Close Order\\" is visible","  Assert \\"Planned In Shipment\\" caption near Edit Shipment and capture for future use.","  Click on svg cross icon ( iconify--simple-line-icons )","  Click on Inventory button from left nav","  Click on Inventory History button from left nav","  Click on iconify--ic svg button for product","  Click on Search(:r4tf:) button","  Click on iconify--flat-color-icons svg button against the captured first product","  Click on Search(:r4p1:) button","  Assert: Check Inventory is reduced in \\"Qty Decr.\\" for the shipment in first row by qtyValue","  Click on Invoice button from left nav","  Click on Shipments To Invoice from left nav","  Enter captured Order # in Order #","  Click on Search(:r5g7:) button","  Select first row checkbox in grid","  Click on Generate Invoice button","  Wait for 2 second and enter invoicecomment in textarea","  Click on Preview Invoice(:r5iu:) button","  Click on ok button","  Assert: Verify Labels - Preview For Invoice, DATE, PAYMENT TERM, DESCRIPTION, Order Item #, PRICE, Unit, Total"]','"IMS login page loads successfully with URL displayed in browser; login form (username, password fields, Login   button) is visible." Username and password are entered in their respective fields; password is masked with dots/asterisks. Login is successful; user is redirected to the IMS dashboard/home page; session is established. Order page loads; Order grid/list is displayed with toolbar (Create New Order button, filters, etc.). "Grid columns are verified and present in the exact order:   - S/O ✓   - S/O NO $ ✓   - Order # ✓   - Customer Name ✓   - Project Name ✓   - Customer PO # ✓   - User Comments ✓   - Vendor PO # ✓   - Deposit ✓   - Salesman ✓   - Order Date ✓   - Last Shipped Date ✓   - Currency ✓   - Status ✓" Create New Order form/page opens; empty order form is displayed with required fields. Supplier Party Id value is entered in the Find Bill Address field. Find dialog/modal opens displaying a grid of suppliers matching the entered Party Id. All rows in the "Company Name" column match the Supplier Party Id criteria — assertion passes. Visible row count ≥ 1 — assertion passes (at least one matching supplier is displayed). "Add button is clicked; selected supplier is added as Bill Address; modal closes; supplier details populate in    the order form." Product search dialog/modal opens for Enter Product Id field. After 2-second wait, Search button is clicked; product grid loads with results. "First product where Stock on S/O (PCS) = 0 AND Actual Yard Stock (PCS) > 0 is identified and captured   (product details stored in variable)." Checkbox of the captured product is selected (checked state = true).  Add Products button is clicked; product is added to the order line items; modal closes. "After 2-sec wait, Save button is clicked; order is saved successfully; success toast/message displayed; page   refreshes to Edit Order view." Order # is captured from the caption near "Edit Order" header (e.g., SO-12345) and stored for later use. Order Actions menu dropdown opens displaying menu items Approve Order menu item is clicked; order status changes to "Approved"; confirmation message displayed. Cross icon (close button) is clicked; current dialog/popup closes; user returns to page. Shipping page loads; Shipping grid/list is displayed. "Grid columns are verified and present in the exact order:   - Order # ✓   - BOL # ✓   - Load # ✓   - Reference # ✓   - Invoice # ✓   - Carrier BOL # ✓   - Shipment Status ✓   - Customer Name ✓   - Project Name ✓   - Customer PO # ✓   - Vendor PO # ✓   - Status ✓   - ETA ✓   - Order Date ✓" Captured Order # is entered in the Order # filter/search field. Submit button is clicked; grid is filtered showing only the matching order row. Edit button on the first row is clicked; Edit Shipment page opens. After 5-second wait, Shipping Carrier autocomplete is filled with the carrier value; carrier is selected. qtyToShip grid cell is populated with qtyValue; value is saved to the cell. "After 2-sec wait, Generate Picklist button is clicked; picklist is generated successfully; success message   displayed." Print dropdown menu opens displaying print options. Print Picklist menu item is clicked; PDF is generated and opens in a new browser tab/window. Page load state is reached (PDF fully loaded). "PDF parsing verifies all required fields/labels are present:   - ITEM # ✓   - Description ✓   - Location ✓   - Qty To Pick (Pcs) ✓   - WEIGHT (lbs) ✓   - Qty Picked ✓   - Heat Number ✓   - Total ✓   - SOLD TO: ✓   - Name Of Carrier: ✓   - SHIP TO: ✓" Browser focus switches to the page whose URL contains url-part (returns to Edit Shipment page). Page load state is reached (page fully loaded). Generate BOL button is clicked; BOL is generated successfully; BOL # is populated; success message displayed. "Close Order" button is visible on the page — assertion passes. """Planned In Shipment"" caption near Edit Shipment header is captured and stored for later use — assertion   passes." Cross icon (close button) is clicked; dialog closes; user returns to Shipping page. Inventory section/menu expands in the left navigation. Inventory History page loads; inventory history grid is displayed with filters. "Product filter/search icon button is clicked; product search dialog opens. " Search button (:r4tf:) is clicked; product list grid populates with results. Selection icon next to the captured first product is clicked; product is selected and applied as filter. Search button (:r4p1:) is clicked; Inventory History grid is filtered for the selected product. "First row\'s ""Qty Decr."" column shows the inventory has been decremented by exactly qtyValue for the shipment   — assertion passes" Uer is able to click on Invoice button User is able to click on Shipment To Invoice Captured Order Is stored User is able to click on search button User is able to select first checkbox Pop up should be shown with prefilled Invoice date as shipment date and comments section below it Preview Invoice screen should be shown with Generate Invoice and cancel button at the bottom Invoice should be generated and that shipment id no longer be displayed on the shipment to Invoice screen User successfully clicked on ok button "Modal contains following labels Preview For Invoice DATE PAYMENT TERM DESCRIPTION  Order Item # PRICE Unit Total"','["url: https://ims.sws.pipe-piling.com/auth/ims/login","username: Puneet","password: ofbiz","Supplier Party Id: ABD Boats","shipping carrier: CHA100 - CHALLENGER LOGISTICS","carrier BOL: B636363","url-part: dashboard/shipment","qtyValue: 1","invoicecomment: Test shipment to invoice"]','2026-04-23 07:30:02','2026-08-27 04:39:25',1,'P1','["functional", "smoke", "core"]',1,0),
